{"command": "python3 -c "
from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
W,H = im.size
d = ImageDraw.Draw(im)
# vertical lines every 0.05 W, horizontal every 0.05 H
for i in range(1,20):
    x = int(W*i/20); d.line([(x,0),(x,H)], fill=(255,80,80), width=2)
    if i%2==0: d.text((x+5, 5), f'{i/20:.2f}', fill=(255,255,0))
for j in range(1,20):
    y = int(H*j/20); d.line([(0,y),(W,y)], fill=(255,80,80), width=2)
    if j%2==0: d.text((5, y+5), f'{j/20:.2f}', fill=(255,255,0))
im.save('crops/grid.png')
print('ok')
"", "description": "Overlay coordinate grid on radiograph"}
